import {allCardInstanceIds,createGame,gameStats,transition,viewFor,type GameCommand,type GameState} from '@madou/engine';
import {getAction} from '@madou/catalog';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
/** S18's CHANT, real intervening turns and locked hit-count roll share one accepted trajectory. */
export function makeScenarioS18(players:{id:string;name:string}[],between=false):GameState {
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,'侍大将のシン');assignCharacter(s,b,'吟遊詩人のレスター');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,spirit:20};s.players[a]!.permanent!.spirit=(s.players[a]!.permanent!.spirit??0)+3-gameStats(s,a).spirit;const sword=takeCard(s,a,'天地百撃斬');trimHand(s,a,sword);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand,dice=Array(100).fill(1)){const input={actorId,command},e={...entropy(),dice},r=transition(s,input,e);if(!r.ok)throw Error(`S18_FIXTURE_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('S18_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('S18_FIXTURE_CARDS');}
 readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});act(a,{type:'CHANT',cardInstanceId:sword});
 for(let n=0;n<50;n++){const actor=s.seatOrder[s.turnSeat]!;if(s.phase==='action'){if(actor===a)break;act(actor,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(actor,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(actor,{type:'END_TURN',discardIds:s.players[actor]!.hand.slice(0,Math.max(0,s.players[actor]!.hand.length-gameStats(s,actor).handLimit))});else if(s.phase==='turn-start')act(actor,{type:'START_TURN'});else if(s.phase==='draw')act(actor,{type:'CHOOSE_DRAW',draw:false});else throw Error('S18_FIXTURE_TURN');}
 act(a,{type:'ATTACK',cardInstanceId:sword,targetIds:[b,c],dedicated:true});for(let n=0;n<300;n++){const w=s.windows?.at(-1);if(w?.kind==='normal-defense'&&w.continuation.kind==='group'&&w.continuation.targetId===b)break;if(!w)throw Error('S18_FIXTURE_WINDOW');act(w.participants[w.cursor]!,{type:'PASS'},w.kind==='damage'&&w.continuation.kind==='action'?[3]:Array(100).fill(1));}
 if(!between)return s;
 const option=viewFor(s,b).abilityOptions.find(o=>o.abilityId==='c2-p03-r2c1-ab01')!;act(b,{type:'USE_ABILITY',abilityId:option.abilityId,targetEventId:option.targetEventId});
 for(let n=0;n<300;n++){const w=s.windows?.at(-1);if(w?.kind==='normal-defense'&&w.continuation.kind==='group'&&w.continuation.targetId===c)return s;if(!w)throw Error('S18_FIXTURE_RESISTANCE');act(w.participants[w.cursor]!,{type:'PASS'},w.kind==='before-roll'?[2,3]:Array(100).fill(1));}throw Error('S18_FIXTURE_LIMIT');
}
